package com.google.gson.internal.bind;

import com.google.gson.Gson;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.lang.reflect.Type;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Tests for the nullSafe parameter in @JsonAdapter annotation.
 */
public class JsonAdapterNullSafeTest {

    // A custom deserializer that returns a special value when null is passed
    private static class NullDeserializer implements JsonDeserializer<String> {
        static final String NULL_VALUE = "null value";

        @Override
        public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
            if (json.isJsonNull()) {
                return NULL_VALUE;
            }
            return json.getAsString();
        }
    }

    // A custom serializer that writes a special string for null
    private static class NullSerializer implements JsonSerializer<String> {
        static final String NULL_STRING = "null string";

        @Override
        public JsonElement serialize(String src, Type typeOfSrc, JsonSerializationContext context) {
            if (src == null) {
                return new JsonPrimitive(NULL_STRING);
            }
            return new JsonPrimitive(src);
        }
    }

    // A class that uses @JsonAdapter with nullSafe = false
    private static class NullUnsafeClass {
        @JsonAdapter(value = NullDeserializer.class, nullSafe = false)
        public String field;
    }

    // A class that uses @JsonAdapter with nullSafe = true (default)
    private static class NullSafeClass {
        @JsonAdapter(value = NullDeserializer.class, nullSafe = true)
        public String field;
    }

    // A combined adapter that acts as both serializer and deserializer
    private static class CombinedAdapter implements JsonSerializer<String>, JsonDeserializer<String> {
        static final String COMBINED_NULL = "combined null";

        @Override
        public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
            if (json.isJsonNull()) {
                return COMBINED_NULL;
            }
            return json.getAsString();
        }

        @Override
        public JsonElement serialize(String src, Type typeOfSrc, JsonSerializationContext context) {
            if (src == null) {
                return new JsonPrimitive(COMBINED_NULL);
            }
            return new JsonPrimitive(src);
        }
    }

    // A class that uses the combined adapter with nullSafe = false
    private static class CombinedNullUnsafe {
        @JsonAdapter(value = CombinedAdapter.class, nullSafe = false)
        public String field;
    }

    @Test
    public void testDeserializeNullUnsafe() {
        // When nullSafe = false, the deserializer should be called for JSON null
        Gson gson = new Gson();
        NullUnsafeClass obj = gson.fromJson("{\"field\":null}", NullUnsafeClass.class);
        assertEquals(NullDeserializer.NULL_VALUE, obj.field);
    }

    @Test
    public void testDeserializeNullSafe() {
        // When nullSafe = true, the deserializer should not be called for JSON null, and field should be null
        Gson gson = new Gson();
        NullSafeClass obj = gson.fromJson("{\"field\":null}", NullSafeClass.class);
        assertNull(obj.field);
    }

    @Test
    public void testSerializeNullUnsafe() {
        // When nullSafe = false, the serializer should be called for a null value
        Gson gson = new Gson();
        CombinedNullUnsafe obj = new CombinedNullUnsafe();
        obj.field = null;
        String json = gson.toJson(obj);
        assertTrue(json.contains(CombinedAdapter.COMBINED_NULL));
    }

    @Test
    public void testSerializeNullSafe() {
        // When nullSafe = true, the serializer should not be called for a null value, and JSON null should be written
        Gson gson = new Gson();
        // Create a class with a serializer that returns a special string for null, but nullSafe = true.
        class NullSafeSerializerClass {
            @JsonAdapter(value = NullSerializer.class, nullSafe = true)
            public String field;
        }
        NullSafeSerializerClass obj = new NullSafeSerializerClass();
        obj.field = null;
        String json = gson.toJson(obj);
        // Because nullSafe = true, the serializer should not be called, and the field should be written as null.
        assertTrue(json.contains("null"));
        assertFalse(json.contains(NullSerializer.NULL_STRING));
    }

    @Test
    public void testCombinedAdapterNullUnsafe() {
        // Test both serialization and deserialization with nullSafe = false
        Gson gson = new Gson();
        // Deserialization
        CombinedNullUnsafe deserialized = gson.fromJson("{\"field\":null}", CombinedNullUnsafe.class);
        assertEquals(CombinedAdapter.COMBINED_NULL, deserialized.field);
        // Serialization
        CombinedNullUnsafe obj = new CombinedNullUnsafe();
        obj.field = null;
        String json = gson.toJson(obj);
        assertTrue(json.contains(CombinedAdapter.COMBINED_NULL));
    }

    // Additional test to directly verify the focal method behavior
    @Test
    public void testTreeTypeAdapterReadNullSafe() throws IOException {
        // This test directly verifies the read method of TreeTypeAdapter with nullSafe = true
        JsonDeserializer<String> deserializer = new JsonDeserializer<String>() {
            @Override
            public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
                return "deserialized";
            }
        };
        // We need to create a TreeTypeAdapter instance. Since it's package-private, we can do it within the same package.
        // We are already in com.google.gson.internal.bind, so we can use the constructor.
        TypeToken<String> typeToken = TypeToken.get(String.class);
        TreeTypeAdapter<String> adapter = new TreeTypeAdapter<String>(null, deserializer, new Gson(), typeToken, null, true);

        // Simulate reading a JSON null value
        com.google.gson.stream.JsonReader reader = new com.google.gson.stream.JsonReader(new java.io.StringReader("null"));
        String result = adapter.read(reader);
        // With nullSafe = true, the deserializer should not be called and result should be null
        assertNull(result);
    }

    @Test
    public void testTreeTypeAdapterReadNullUnsafe() throws IOException {
        JsonDeserializer<String> deserializer = new JsonDeserializer<String>() {
            @Override
            public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
                return "deserialized";
            }
        };
        TypeToken<String> typeToken = TypeToken.get(String.class);
        TreeTypeAdapter<String> adapter = new TreeTypeAdapter<String>(null, deserializer, new Gson(), typeToken, null, false);

        com.google.gson.stream.JsonReader reader = new com.google.gson.stream.JsonReader(new java.io.StringReader("null"));
        String result = adapter.read(reader);
        // With nullSafe = false, the deserializer should be called
        assertEquals("deserialized", result);
    }
}

